sealed class FakeClock : IClock {
    public Func<DateTime> Now { get; set; } = () => DateTime.UnixEpoch;
    DateTime IClock.Now => Now();
}

var clock = new FakeClock { Now = () => throw new TimeoutException() };
var session = new Session(clock, TimeSpan.FromMinutes(30));

sealed class ConfiguredProxy : DispatchProxy {
    public Dictionary<string, object?> Responses { get; } = new();
    protected override object? Invoke(MethodInfo target, object?[]? args) =>
        Responses.TryGetValue(target.Name, out var value) ? value : default;
}

var clock = DispatchProxy.Create<IClock, ConfiguredProxy>();
((ConfiguredProxy)(object)clock).Responses["get_Now"] = DateTime.UnixEpoch;
